// Function to combine elements from multiple ranges into one array
int combine_elements_from_ranges(float arr[], int ranges[][2], int num_ranges, float combined[]) {
  int combined_size = 0;

  // Iterate over each range
  for (int i = 0; i < num_ranges; i++) {
      int start = ranges[i][0];
      int end = ranges[i][1];

      // Add the elements from the current range into the combined array
      for (int j = start; j <= end; j++) {
          combined[combined_size] = arr[j];
          combined_size++;
      }
  }

  return combined_size;  // Return the size of the combined array
}

// Function to calculate the sum of all elements in an array
float array_sum(float arr[], int size) {
  float sum = 0.0;
  
  // Loop through the array and add each element to the sum
  for (int i = 0; i < size; i++) {
      sum += arr[i];
  }
  
  return sum;
}

// Function to find the most probable (mode) value using bucketization
float find_mode_with_buckets(float arr[], int size, float precision) {
  int bucket_count = 0;

  const int bucket_size = (int)(1 / precision);
  float bucket_map[bucket_size];  // Array to store frequency of each bucket
  for (int i = 0; i < bucket_size; i++) {
      bucket_map[i] = 0;
  }

  for (int i = 0; i < size; i++) {
      // Round the value to the nearest bucket based on the precision
      int bucket_index = (int)(arr[i] / precision);
      bucket_map[bucket_index]++;
  }

  // Find the bucket with the maximum frequency
  int max_count = 0;
  float mode = 0;
  for (int i = 0; i < bucket_size; i++) {
      if (bucket_map[i] > max_count) {
          max_count = bucket_map[i];
          mode = (i * precision);  // Convert back to the original value range
      }
  }
  return mode;
}


int main() {
  float output_array[384];

  clock_t start, end;
  float cpu_time_used;

  // Start time
  start = clock();

  model_inference(input_image, output_array);

  // End time
  end = clock();

  // Calculate the elapsed time
  cpu_time_used = ((float) (end - start)) / CLOCKS_PER_SEC;

  // print model ouput
  printf("model output: \n");

  // loop array
  for (int i = 0; i < 384; i++) {
    printf("%f ", output_array[i]);
    if ((i + 1) % 32 == 0) {
        printf("\n");  // Print new line after every 16th element
    }
  }

  // Define ranges to calculate the average for
  int ranges[box_height][2] = {
    {5, 10},   // grid 6-11
    {21, 26},  // grid 22-27
    {37, 42},  // grid 38-43
    {53, 58}   // grid 54-59
  };

  // Make combined array
  float box_array[box_height * box_width];
  int combined_size = combine_elements_from_ranges(output_array, ranges, box_height, box_array);
  // Calculate the sum of the array
  float sum = array_sum(box_array, combined_size);

  // Print sum and total_elements
  // printf("Sum of the combined grid: %f\n", sum);
  // printf("Total elements in the combined grid: %d\n", combined_size);

  // Calculate the average
  float combined_average = (float)sum / combined_size;
  // Print the average
  printf("Average of top-mid part of grid: %f\n", combined_average);

  // Find and print the mode of the combined array
  float mode_value = find_mode_with_buckets(box_array, combined_size, 0.02);
  printf("Most probable mode value in this box is: %f\n", mode_value);

  // Print speed
  printf("Time taken by function: %f seconds\n", cpu_time_used);
  
return 0;
}